import{_ as i,o as t,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse(`{"title":"ioBroker Blockly","description":"Introduction à Blockly, intégré à l'adaptateur JavaScript d'ioBroker, à travers un exemple de démarrage officiel.","frontmatter":{"title":"ioBroker Blockly","description":"Introduction à Blockly, intégré à l'adaptateur JavaScript d'ioBroker, à travers un exemple de démarrage officiel."},"headers":[],"relativePath":"fr/blog/snippets/iobroker-blockly.md","filePath":"fr/blog/snippets/iobroker-blockly.md","lastUpdated":1793126673000}`),l={name:"fr/blog/snippets/iobroker-blockly.md"};function o(n,e,s,c,d,p){return t(),r("div",null,[...e[0]||(e[0]=[a(`<p><a id="statut"></a></p><h1 id="iobroker-blockly" tabindex="-1">ioBroker Blockly <a class="header-anchor" href="#iobroker-blockly" aria-label="Permalink to &quot;ioBroker Blockly {#iobroker-blockly}&quot;">​</a></h1><p>Blockly est l&#39;éditeur de scripts graphique de l&#39;<strong>adaptateur JavaScript d&#39;ioBroker</strong>. Les automatisations sont construites à l&#39;aide de blocs, ce qui évite d&#39;avoir à rédiger manuellement l&#39;intégralité du code JavaScript.</p><div class="info custom-block"><p class="custom-block-title">Documentation officielle</p><p>Cette page ne propose qu&#39;une brève introduction. La description complète de tous les blocs ainsi que d&#39;autres exemples sont disponibles dans la documentation officielle d&#39;ioBroker.</p></div><h2 id="offizielle-quellen" tabindex="-1">Sources officielles <a class="header-anchor" href="#offizielle-quellen" aria-label="Permalink to &quot;Sources officielles {#offizielle-quellen}&quot;">​</a></h2><ul><li><a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noreferrer">ioBroker.javascript – dépôt officiel</a></li><li><a href="https://github.com/ioBroker/ioBroker.javascript/tree/master/docs/de" target="_blank" rel="noreferrer">Documentation de l&#39;adaptateur JavaScript (en allemand)</a></li><li><a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/docs/de/blockly.md" target="_blank" rel="noreferrer">Documentation complète de Blockly</a></li></ul><h2 id="beispiel-1-datenpunkt-abhangig-von-einem-anderen-datenpunkt-schalten" tabindex="-1">Exemple 1 : Commuter un point de données en fonction d&#39;un autre point de données <a class="header-anchor" href="#beispiel-1-datenpunkt-abhangig-von-einem-anderen-datenpunkt-schalten" aria-label="Permalink to &quot;Exemple 1 : Commuter un point de données en fonction d&#39;un autre point de données {#beispiel-1-datenpunkt-abhangig-von-einem-anderen-datenpunkt-schalten}&quot;">​</a></h2><p>L&#39;exemple d&#39;introduction officiel illustre un scénario typique de détection de mouvement :</p><ul><li>Un point de données lié au mouvement sert de déclencheur.</li><li>Lors d&#39;un changement d&#39;état, un point de données lié à l&#39;éclairage est piloté.</li><li>La valeur actuelle du détecteur de mouvement est transmise au point de données de l&#39;éclairage.</li><li>La détection d&#39;un mouvement allume la lumière.</li><li>L&#39;absence de mouvement éteint la lumière.</li></ul><p><a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/docs/de/blockly.md#beispiel-1" target="_blank" rel="noreferrer"><img src="https://raw.githubusercontent.com/ioBroker/ioBroker.javascript/master/docs/de/img/getting_started_1_de.png" alt="Exemple Blockly officiel n° 1 pour ioBroker"></a></p><small> Source de l&#39;image et droits : L&#39;image provient du dépôt officiel <a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noopener">ioBroker.javascript</a>. Les droits et les conditions de licence sont régis par le projet qui y est publié et par sa licence associée. </small><h2 id="benotigte-blockly-blocke" tabindex="-1">Blocs Blockly nécessaires <a class="header-anchor" href="#benotigte-blockly-blocke" aria-label="Permalink to &quot;Blocs Blockly nécessaires {#benotigte-blockly-blocke}&quot;">​</a></h2><h3 id="_1-trigger" tabindex="-1">1. Déclencheur (Trigger) <a class="header-anchor" href="#_1-trigger" aria-label="Permalink to &quot;1. Déclencheur (Trigger) {#_1-trigger}&quot;">​</a></h3><p>Dans la catégorie <strong>Déclencheur</strong> (Trigger), on utilise le bloc <strong>Si objet</strong> (Falls Objekt).</p><p>On y sélectionne le point de données correspondant au détecteur de mouvement.</p><h3 id="_2-datenpunkt-steuern" tabindex="-1">2. Piloter un point de données <a class="header-anchor" href="#_2-datenpunkt-steuern" aria-label="Permalink to &quot;2. Piloter un point de données {#_2-datenpunkt-steuern}&quot;">​</a></h3><p>Dans la catégorie <strong>Système</strong>, on insère le bloc <strong>Piloter</strong> (Steuere).</p><p>Le point de données correspondant à l&#39;éclairage est sélectionné comme cible.</p><h3 id="_3-wert-ubernehmen" tabindex="-1">3. Récupérer la valeur <a class="header-anchor" href="#_3-wert-ubernehmen" aria-label="Permalink to &quot;3. Récupérer la valeur {#_3-wert-ubernehmen}&quot;">​</a></h3><p>Le bloc « commander » (ou « piloter ») intègre la <strong>valeur de l&#39;ID d&#39;objet</strong>.</p><p>On y sélectionne à nouveau le point de données correspondant au mouvement. Ainsi, l&#39;éclairage adopte l&#39;état actuel (Vrai/Faux) du détecteur de mouvement.</p><h2 id="vereinfachter-ablauf" tabindex="-1">Processus simplifié <a class="header-anchor" href="#vereinfachter-ablauf" aria-label="Permalink to &quot;Processus simplifié {#vereinfachter-ablauf}&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Falls sich der Bewegungsmelder ändert</span></span>
<span class="line"><span>    setze den Zustand des Lichts</span></span>
<span class="line"><span>    auf den aktuellen Wert des Bewegungsmelders</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="blockly-importieren" tabindex="-1">Importer le bloc Blockly <a class="header-anchor" href="#blockly-importieren" aria-label="Permalink to &quot;Importer le bloc Blockly {#blockly-importieren}&quot;">​</a></h2><p>Le code XML complet, prêt à être importé, est fourni dans la documentation officielle, juste en dessous de l&#39;<strong>Exemple 1</strong> :</p><p><a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/docs/de/blockly.md#beispiel-1" target="_blank" rel="noreferrer">Ouvrir l&#39;Exemple 1 avec le code XML Blockly</a></p><p>Il suffit de copier ce code XML et de l&#39;insérer dans l&#39;éditeur Blockly via la fonction d&#39;importation.</p><h2 id="weitere-offizielle-beispiele" tabindex="-1">Autres exemples officiels <a class="header-anchor" href="#weitere-offizielle-beispiele" aria-label="Permalink to &quot;Autres exemples officiels {#weitere-offizielle-beispiele}&quot;">​</a></h2><p>La documentation officielle propose également :</p><ul><li><strong>Exemple 2 :</strong> Allumer la lumière en cas de détection de mouvement et l&#39;éteindre après dix minutes sans nouveau mouvement.</li><li><strong>Exemple 3 :</strong> Envoyer un e-mail lorsque la température extérieure dépasse un certain seuil.</li></ul><p><a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/docs/de/blockly.md#getting-started" target="_blank" rel="noreferrer">Voir tous les exemples officiels Blockly</a></p><h2 id="eigene-blockly-beitrage-im-blog" tabindex="-1">Partager vos propres exemples Blockly sur le blog <a class="header-anchor" href="#eigene-blockly-beitrage-im-blog" aria-label="Permalink to &quot;Partager vos propres exemples Blockly sur le blog {#eigene-blockly-beitrage-im-blog}&quot;">​</a></h2><p>Pour vos propres exemples, la structure suivante est recommandée :</p><ol><li>Décrire la tâche</li><li>Indiquer les ID d&#39;objets nécessaires</li><li>Insérer une capture d&#39;écran de la configuration Blockly</li><li>Fournir le code XML Blockly exporté</li><li>Expliquer les adaptations et les prérequis</li></ol><p>Les captures d&#39;écran sont stockées dans le projet de documentation ici :</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/public/images/blog/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Intégration dans l&#39;article :</p><div class="language-md vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">ioBroker Blockly</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">/images/blog/mein-blockly.png</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Les ID d&#39;objets présents dans les exemples doivent toujours être adaptés à votre propre système ioBroker.</p></div>`,39)])])}const b=i(l,[["render",o]]);expor